mapper.select:
SELECT COALESCE(NULLIF(#{course}, ''), '全部课程') AS courseName, COALESCE(NULLIF(#{college}, ''), '全校') AS college, COALESCE(NULLIF(#{semester}, ''), '当前学年') AS semester, ROUND(IFNULL(( SELECT COUNT(DISTINCT CASE WHEN lr.task_point_id IS NOT NULL THEN lr.user_id END) * 100.0 / NULLIF(COUNT(DISTINCT lr.user_id), 0) FROM learning_record lr JOIN course c ON c.course_id = lr.course_id JOIN `user` u ON u.id = lr.user_id AND u.role = 'student' AND u.is_deleted = 0
), 0), 2) AS taskCompletionRate, ROUND(IFNULL(( SELECT COUNT(DISTINCT CASE WHEN lr.is_online = 1 THEN lr.user_id END) * 100.0 / NULLIF(COUNT(DISTINCT lr.user_id), 0) FROM learning_record lr JOIN course c ON c.course_id = lr.course_id JOIN `user` u ON u.id = lr.user_id AND u.role = 'student' AND u.is_deleted = 0
), 0), 2) AS videoCompletionRate, ROUND(IFNULL(( SELECT COUNT(DISTINCT CASE WHEN lr.task_point_id IS NOT NULL AND lr.check_in_time IS NOT NULL THEN lr.user_id END) * 100.0 / NULLIF(COUNT(DISTINCT lr.user_id), 0) FROM learning_record lr JOIN course c ON c.course_id = lr.course_id JOIN `user` u ON u.id = lr.user_id AND u.role = 'student' AND u.is_deleted = 0
), 0), 2) AS quizCompletionRate, ROUND(IFNULL(( SELECT COUNT(DISTINCT CASE WHEN lr.task_point_id IS NOT NULL THEN lr.user_id END) * 100.0 / NULLIF(COUNT(DISTINCT lr.user_id), 0) FROM learning_record lr JOIN course c ON c.course_id = lr.course_id JOIN `user` u ON u.id = lr.user_id AND u.role = 'student' AND u.is_deleted = 0
), 0), 2) AS assignmentCompletionRate, ROUND(IFNULL(( SELECT COUNT(DISTINCT CASE WHEN lr.check_in_time IS NOT NULL THEN lr.user_id END) * 100.0 / NULLIF(COUNT(DISTINCT lr.user_id), 0) FROM learning_record lr JOIN course c ON c.course_id = lr.course_id JOIN `user` u ON u.id = lr.user_id AND u.role = 'student' AND u.is_deleted = 0
), 0), 2) AS examCompletionRate, IFNULL(( SELECT COUNT(DISTINCT lr.task_point_id) FROM learning_record lr JOIN course c ON c.course_id = lr.course_id JOIN `user` u ON u.id = lr.user_id AND u.role = 'student' AND u.is_deleted = 0
), 0) AS chapterStudyCount, ROUND(IFNULL(( SELECT COUNT(DISTINCT CASE WHEN lr.check_in_time IS NOT NULL THEN lr.user_id END) * 100.0 / NULLIF(COUNT(DISTINCT lr.user_id), 0) FROM learning_record lr JOIN course c ON c.course_id = lr.course_id JOIN `user` u ON u.id = lr.user_id AND u.role = 'student' AND u.is_deleted = 0
), 0), 2) AS checkinCompletionRate, ROUND(IFNULL(( SELECT COUNT(DISTINCT CASE WHEN lr.task_point_id IS NOT NULL THEN lr.user_id END) * 100.0 / NULLIF(COUNT(DISTINCT lr.user_id), 0) FROM learning_record lr JOIN course c ON c.course_id = lr.course_id JOIN `user` u ON u.id = lr.user_id AND u.role = 'student' AND u.is_deleted = 0
), 0), 2) AS schoolTaskCompletionRate, ROUND(IFNULL(( SELECT COUNT(DISTINCT CASE WHEN lr.is_online = 1 THEN lr.user_id END) * 100.0 / NULLIF(COUNT(DISTINCT lr.user_id), 0) FROM learning_record lr JOIN course c ON c.course_id = lr.course_id JOIN `user` u ON u.id = lr.user_id AND u.role = 'student' AND u.is_deleted = 0
), 0), 2) AS schoolVideoCompletionRate, ROUND(IFNULL(( SELECT COUNT(DISTINCT CASE WHEN lr.task_point_id IS NOT NULL AND lr.check_in_time IS NOT NULL THEN lr.user_id END) * 100.0 / NULLIF(COUNT(DISTINCT lr.user_id), 0) FROM learning_record lr JOIN course c ON c.course_id = lr.course_id JOIN `user` u ON u.id = lr.user_id AND u.role = 'student' AND u.is_deleted = 0
), 0), 2) AS schoolQuizCompletionRate, ROUND(IFNULL(( SELECT COUNT(DISTINCT CASE WHEN lr.task_point_id IS NOT NULL THEN lr.user_id END) * 100.0 / NULLIF(COUNT(DISTINCT lr.user_id), 0) FROM learning_record lr JOIN course c ON c.course_id = lr.course_id JOIN `user` u ON u.id = lr.user_id AND u.role = 'student' AND u.is_deleted = 0
), 0), 2) AS schoolAssignmentCompletionRate, ROUND(IFNULL(( SELECT COUNT(DISTINCT CASE WHEN lr.check_in_time IS NOT NULL THEN lr.user_id END) * 100.0 / NULLIF(COUNT(DISTINCT lr.user_id), 0) FROM learning_record lr JOIN course c ON c.course_id = lr.course_id JOIN `user` u ON u.id = lr.user_id AND u.role = 'student' AND u.is_deleted = 0
), 0), 2) AS schoolExamCompletionRate, IFNULL(( SELECT COUNT(DISTINCT lr.task_point_id) FROM learning_record lr JOIN course c ON c.course_id = lr.course_id JOIN `user` u ON u.id = lr.user_id AND u.role = 'student' AND u.is_deleted = 0
), 0) AS schoolChapterStudyCount, ROUND(IFNULL(( SELECT COUNT(DISTINCT CASE WHEN lr.check_in_time IS NOT NULL THEN lr.user_id END) * 100.0 / NULLIF(COUNT(DISTINCT lr.user_id), 0) FROM learning_record lr JOIN course c ON c.course_id = lr.course_id JOIN `user` u ON u.id = lr.user_id AND u.role = 'student' AND u.is_deleted = 0
), 0), 2) AS schoolCheckinCompletionRate
